import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry (512x320 atlas region = 1.6:1 aspect ratio)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Load texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material with TSL node
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = TSL.texture(texture);

  // Create and configure plane
  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(
    config.scenePosition.x,
    config.scenePosition.y,
    config.scenePosition.z
  );
  plane.rotation.set(
    config.sceneRotation.x,
    config.sceneRotation.y,
    config.sceneRotation.z
  );
  plane.scale.set(
    config.sceneScale.x,
    config.sceneScale.y,
    config.sceneScale.z
  );

  group.add(plane);

  // Render text content
  if (config.textContent && config.textContent.length > 0) {
    config.textContent.forEach((text) => {
      const textMesh = ctx.fontAtlas.createText(text.content, {
        fontSize: text.fontSize || 0.34,
        fontWeight: text.fontWeight || 400,
        fontFamily: 'Lora',
      });

      if (textMesh) {
        textMesh.position.z = 0.01;
        plane.add(textMesh);
      }
    });
  }

  // Setup handlers
  group.userData.handlers = {};

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
